public class InvoiceSyncQueueable implements Queueable, Database.AllowsCallouts {
  private List<Id> remainingIds;
  private Integer retryCount;
  private static final Integer MAX_RETRIES = 3;
  private static final Integer BATCH_SIZE = 50;

  public InvoiceSyncQueueable(List<Id> ids, Integer retryCount) {
    this.remainingIds = ids;
    this.retryCount = retryCount;
  }

  public void execute(QueueableContext context) {
    List<Id> currentBatch = new List<Id>();
    Integer size = Math.min(BATCH_SIZE, remainingIds.size());
    for (Integer i = 0; i < size; i++) currentBatch.add(remainingIds[i]);
    List<Id> nextRemaining = new List<Id>(remainingIds);
    nextRemaining.removeAll(currentBatch);

    try {
      ExternalInvoiceService.syncBatch(currentBatch);
    } catch (CalloutException ex) {
      if (retryCount < MAX_RETRIES) {
        System.enqueueJob(new InvoiceSyncQueueable(currentBatch, retryCount + 1));
        return;
      }
      ErrorLogger.log('InvoiceSync failed after max retries', ex, currentBatch);
      return;
    }

    if (!nextRemaining.isEmpty() && !Test.isRunningTest()) {
      System.enqueueJob(new InvoiceSyncQueueable(nextRemaining, 0));
    }
  }
}

public class CaseReparentBatch implements Database.Batchable<SObject>, Database.Stateful {
  private Id oldAccountId;
  private Id newAccountId;
  public Integer totalProcessed = 0;

  public CaseReparentBatch(Id oldAccountId, Id newAccountId) {
    this.oldAccountId = oldAccountId;
    this.newAccountId = newAccountId;
  }

  public Database.QueryLocator start(Database.BatchableContext bc) {
    return Database.getQueryLocator([
      SELECT Id, AccountId FROM Case WHERE AccountId = :oldAccountId
    ]);
  }

  public void execute(Database.BatchableContext bc, List<Case> scope) {
    for (Case c : scope) c.AccountId = newAccountId;
    Database.SaveResult[] results = Database.update(scope, false);
    Integer successCount = 0;
    for (Database.SaveResult sr : results) if (sr.isSuccess()) successCount++;
    totalProcessed += successCount;
  }

  public void finish(Database.BatchableContext bc) {
    System.debug('Reparented ' + totalProcessed + ' cases from ' + oldAccountId + ' to ' + newAccountId);
    NotificationService.notifyAdmin('Case reparent complete: ' + totalProcessed + ' records.');
  }
}

