  public List<Contact> selectByAccountIds(Set<Id> accountIds) {
    List<Contact> results = [
      SELECT Id, FirstName, LastName, Email, Phone, AccountId
      FROM Contact
      WHERE AccountId IN :accountIds
      WITH USER_MODE
