// Problem: calling this from inside a trigger context (which already has depth 1),
// then it enqueues depth 2 -- but if the ORIGINAL caller was already async
// (e.g. invoked from another Queueable or from a Platform Event trigger that's
// itself part of an async context), the synchronous-context allowance of 1
// additional job is already exhausted.
public class BadExampleQueueable implements Queueable {
  public void execute(QueueableContext context) {
    // ... work ...
    System.enqueueJob(new BadExampleQueueable()); // depth +1 each time
  }
}

// Fix: don't rely on unconditional re-enqueue; check isQueueable() and
// fall back to a different async mechanism (e.g. Batch Apex) if the
// queueable depth limit would be exceeded, or restructure so chaining
// originates from a synchronous context, not nested inside another async job.
public class FixedExampleQueueable implements Queueable {
  private List<Id> remaining;
  public FixedExampleQueueable(List<Id> remaining) { this.remaining = remaining; }

  public void execute(QueueableContext context) {
    // ... process current chunk ...
    List<Id> nextChunk = ProcessingUtil.nextChunk(remaining);
    if (!nextChunk.isEmpty()) {
      if (Limits.getLimitQueueableJobs() - Limits.getQueueableJobs() > 0) {
        System.enqueueJob(new FixedExampleQueueable(nextChunk));
      } else {
        BatchJobLauncher.launchFallbackBatch(nextChunk); // escalate to Batch Apex instead
      }
    }
  }
}

